          txMinedPromise->Promise.getOk(txOutcome => {
            Js.log(txOutcome)
            setTxState(_ => Complete(txOutcome))
          })
          txMinedPromise->Promise.getError(error => {
            setTxState(_ => Failed)
            Js.log(error)
          })
          ()
        })
        updatePricePromise->Promise.getError(error => setTxState(_ => Declined(error.message)))
