  <div>
    {if hasForTrade {
      <Section username list=ForTrade userItems=forTradeList editable />
    } else {
      React.null
    }}
    {if hasCanCraft {
      <Section username list=CanCraft userItems=canCraftList editable />
    } else {
      React.null
    }}
    {if hasWishlist {
      <Section username list=Wishlist userItems=wishlist editable />
    } else {
      React.null
    }}
    {if hasCatalogOnly {
      <Section
        username
        list=Catalog
